#!/bin/sh
# Copyright 2026 James Casey
# SPDX-License-Identifier: Apache-2.0
#
# Generated by `beamtalk release` — ADR 0125 §1.6/§1.7 (BT-3573). Do not edit;
# it is overwritten on every `beamtalk release`.
#
# Verbs: foreground (default) | stop | ping | remote_console | eval | rpc | version
set -eu

RELEASE_NAME="__RELEASE_NAME__"
RELEASE_VSN="__RELEASE_VSN__"
ERTS_VSN="__ERTS_VERSION__"
INCLUDE_ERTS="__INCLUDE_ERTS__"

# BT-5134: resolve a symlinked `bin/<name>` (e.g. /usr/local/bin/<name> ->
# <root>/bin/<name>) to the real script before locating the release root.
# BT-5187: bounded, so a symlink cycle is an error rather than a hang.
SELF="$0"
LINK_HOPS=0
while [ -h "$SELF" ]; do
    LINK_HOPS=$((LINK_HOPS + 1))
    if [ "$LINK_HOPS" -gt 40 ]; then
        echo "error: too many levels of symbolic links resolving '$0'" >&2
        exit 1
    fi
    LINK_TARGET=$(readlink -- "$SELF")
    case "$LINK_TARGET" in
        /*) SELF="$LINK_TARGET" ;;
        *) SELF="$(dirname -- "$SELF")/$LINK_TARGET" ;;
    esac
done
SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$SELF")" && pwd -P)
ROOT=$(CDPATH= cd -- "$SCRIPT_DIR/.." && pwd -P)
CONFIG_DIR="$ROOT/releases/$RELEASE_VSN"
PROVENANCE="$CONFIG_DIR/beamtalk-provenance.json"

# Resolve the erl to run: bundled ERTS when present (the default), else the
# host `erl` on PATH (ADR 0125 §1.3/§3.2). Cross-compilation is not
# supported, so a bundled ERTS is always for this host/arch.
if [ "$INCLUDE_ERTS" = "true" ] && [ -x "$ROOT/erts-$ERTS_VSN/bin/erl" ]; then
    ERL="$ROOT/erts-$ERTS_VSN/bin/erl"
    USING_HOST_ERTS=false
else
    ERL=$(command -v erl 2>/dev/null || true)
    if [ -z "$ERL" ]; then
        echo "error: no Erlang/OTP found — no bundled ERTS in '$ROOT', and 'erl' is not on PATH" >&2
        exit 1
    fi
    USING_HOST_ERTS=true
fi

# Pin epmd to loopback (ADR 0125 §1.6: distribution is always loopback-bound)
# for every verb below that can start distribution or epmd itself — epmd is
# a shared, per-host daemon that keeps whichever bind address the *first*
# thing to start it gave it, so this must be set before any `-sname` erl
# invocation, not just `foreground`'s. Mirrors `startup_command.rs`'s
# identical `ERL_EPMD_ADDRESS` pin for the dev workspace/REPL launchers.
ERL_EPMD_ADDRESS=127.0.0.1
export ERL_EPMD_ADDRESS

# BT-5127: the client verbs below (`stop`/`ping`/`rpc`/`remote_console`)
# start distributed nodes too, and the foreground node's `vm.args` pin
# does not reach them. Each passes `-kernel inet_dist_use_interface
# '{127,0,0,1}'` (the same value as `vm.args`) so no node this launcher
# starts listens for distribution off loopback.

# Reject a malformed RELEASE_NODE before it ever reaches `erl` — an invalid
# `-sname` (e.g. containing '/', '@', '.', or whitespace) otherwise crashes
# the whole node with a raw kernel crash dump ("Invalid node name!",
# verified empirically) instead of a clean, actionable error like every
# other operator-facing failure this launcher produces. Same charset as the
# CLI's own `validate_workspace_name` (dev workspace IDs) — letters,
# digits, `-`, `_` only; no `@`/`.` since `node_sname` always appends
# `@localhost` itself.
case "${RELEASE_NODE:-}" in
    '') ;;
    *[!A-Za-z0-9_-]*)
        echo "error: RELEASE_NODE '$RELEASE_NODE' is not a valid instance name (letters, digits, '-', '_' only)" >&2
        exit 2
        ;;
esac

# ADR 0125 §3.2 — under a host ERTS, refuse to boot outside the OTP major
# window this artifact's BEAM files are guaranteed to load on
# (host_major in [build_major, build_major + 2]). Not applicable when the
# release bundles its own ERTS: the artifact is exact.
check_otp_window() {
    [ "$USING_HOST_ERTS" = "true" ] || return 0
    [ -f "$PROVENANCE" ] || return 0
    req_min=$(grep -o '"min"[[:space:]]*:[[:space:]]*[0-9]*' "$PROVENANCE" | head -n1 | grep -o '[0-9]*$' || true)
    req_max=$(grep -o '"max"[[:space:]]*:[[:space:]]*[0-9]*' "$PROVENANCE" | head -n1 | grep -o '[0-9]*$' || true)
    built_otp_release=$(grep -o '"otp_release"[[:space:]]*:[[:space:]]*"[^"]*"' "$PROVENANCE" | head -n1 | sed -E 's/.*"([^"]*)"$/\1/')
    built_major=${built_otp_release%%-*}
    host_major=$("$ERL" -noshell -eval 'io:format("~s", [erlang:system_info(otp_release)]), halt().' 2>/dev/null | grep -o '^[0-9]*' || true)
    if [ -z "$host_major" ] || [ -z "$req_min" ] || [ -z "$req_max" ]; then
        return 0
    fi
    if [ "$host_major" -lt "$req_min" ] || [ "$host_major" -gt "$req_max" ]; then
        echo "$RELEASE_NAME $RELEASE_VSN cannot start on Erlang/OTP $host_major." >&2
        echo "" >&2
        echo "  This release's BEAM files were produced by OTP $built_major and will not load on" >&2
        echo "  an older VM." >&2
        echo "" >&2
        echo "  Required: Erlang/OTP $req_min-$req_max (built on $built_major)" >&2
        echo "  Found:    Erlang/OTP $host_major ($ERL)" >&2
        echo "" >&2
        echo "  Either install a supported Erlang/OTP version, or rebuild the release on this host." >&2
        exit 1
    fi
}

# `-boot` for every verb below *except* `foreground` — none of them may boot
# the full release (that would start the project's own application a second
# time). With no `-boot` flag, `erl` falls back to `$ROOTDIR/bin/start.boot`;
# with the bundled ERTS, this binary's own root-directory autodetection
# resolves `$ROOTDIR` to `$ROOT` (the release dir), which has no such file.
# `copy_erts` (BT-3571/BT-3573) copies a plain kernel+stdlib
# `start_clean.boot` alongside the bundled ERTS for exactly this — point at
# it explicitly when it is present; a host ERTS already has its own
# `$ROOTDIR/bin/start.boot` (a real OTP install always ships one), so no
# flag is needed there.
minimal_boot_args() {
    if [ "$INCLUDE_ERTS" = "true" ] && [ -f "$ROOT/erts-$ERTS_VSN/bin/start_clean.boot" ]; then
        printf -- '-boot '
        sq "$ROOT/erts-$ERTS_VSN/bin/start_clean"
    fi
}

# BT-5067: a release root may contain spaces (`/opt/My App/rel`), so the
# argument helpers below print each word single-quoted (`sq`) and the verbs
# splice them back with `eval "set -- ..."` — never an unquoted `$(...)`
# expansion, which word-splits on the space and breaks `-pa`/`-boot`.
# Prints one single-quoted word followed by a space.
sq() {
    printf "'"
    printf '%s' "$1" | sed "s/'/'\\\\''/g"
    printf "' "
}

# Every `lib/*/ebin` directory, as `-pa` flags — needed by `eval` (loads the
# runtime closure into a fresh VM with no boot script) and by the
# distribution clients (`stop`/`ping`/`rpc`), which reference
# `beamtalk_release_launcher` and `beamtalk_error` by name.
lib_pa_args() {
    for d in "$ROOT"/lib/*/ebin; do
        if [ -d "$d" ]; then
            printf -- '-pa '
            sq "$d"
        fi
    done
}

# A short, collision-resistant node name for the throwaway client nodes
# (`stop`/`ping`/`rpc`) — `-hidden` and loopback-bound, so it never appears
# in the foreground node's regular node list.
client_sname() {
    printf '%s_%s_%s' "$RELEASE_NAME" "$1" "$$"
}

# BT-5126 / BT-5185: the cookie never goes on erl's command line (a cookie
# flag, `ERL_AFLAGS` and `-args_file` all expand into the emulator's argv,
# which any local user can read from `ps`), and the node never runs
# with any other cookie, not even while it boots: a connection made then
# stays authenticated after the cookie changes. The release cookie is both
# the distribution and console cookie, so either would be code execution as
# the service user. Instead the cookie goes in `.erlang.cookie` (0400) in a
# fresh private (0700) directory that erl is started with as its `HOME`
# (the only variable erlexec derives `-home` from), so OTP's `auth` reads it
# as the kernel boots. `__COOKIE_HOME_ENV__` names the directory and
# `__ORIG_PREFIX__HOME` the `HOME` it replaced; the node puts `HOME` back and
# removes the directory first thing (`__RESTORE_HOME_EVAL__`: a leading
# `-eval` for the client verbs, `beamtalk_runtime_app:start/2` for the
# foreground node). `RELEASE_COOKIE` is unset, so no process erl starts
# (epmd included) inherits it. A host `erl` found on PATH may be a version
# manager's shim (mise, asdf) that needs the real `HOME` to find its Erlang,
# so it is first resolved to the installation's own `bin/erl`, which does not.
# Must run in the main shell (not a `$(...)` subshell) so the exports stick.
COOKIE_HOME_DIR=""
export_cookie() {
    [ -n "${RELEASE_COOKIE:-}" ] || return 0
    case "$RELEASE_COOKIE" in
        -* | +*)
            echo "error: RELEASE_COOKIE must not start with '-' or '+'" >&2
            exit 2
            ;;
        *[[:space:]\"\'\\]*)
            echo "error: RELEASE_COOKIE must not contain whitespace, quotes or backslashes" >&2
            exit 2
            ;;
    esac
    cookie_home=$(umask 077 && mktemp -d "${TMPDIR:-/tmp}/beamtalk-cookie.XXXXXX") || {
        echo "error: could not create a private directory for the cookie" >&2
        exit 1
    }
    COOKIE_HOME_DIR="$cookie_home"
    # From here on a signal (Ctrl-C, `timeout`, a supervisor) removes the
    # directory, and stops a client `run_client` started. A `kill` of an
    # exited client must not abort the trap under `set -e`. `exec` (the
    # foreground node, `remote_console`) drops these traps.
    erl_pid=
    trap '[ -z "$erl_pid" ] || kill "$erl_pid" 2>/dev/null || :; cleanup_cookie_home; exit 130' INT
    trap '[ -z "$erl_pid" ] || kill "$erl_pid" 2>/dev/null || :; cleanup_cookie_home; exit 143' TERM
    trap '[ -z "$erl_pid" ] || kill "$erl_pid" 2>/dev/null || :; cleanup_cookie_home; exit 129' HUP
    if ! (umask 277 && printf '%s' "$RELEASE_COOKIE" > "$cookie_home/.erlang.cookie"); then
        rm -rf "$cookie_home"
        echo "error: could not write the cookie file" >&2
        exit 1
    fi
    if [ "$USING_HOST_ERTS" = "true" ]; then
        erl_root=$("$ERL" -noshell -noinput -boot no_dot_erlang \
            -eval 'io:format("erl-root:~ts~n", [code:root_dir()]), halt().' 2>/dev/null |
            sed -n 's/^erl-root://p' | head -n1) || erl_root=""
        if [ -n "$erl_root" ] && [ -x "$erl_root/bin/erl" ]; then
            ERL="$erl_root/bin/erl"
        fi
    fi
    if [ -n "${HOME+x}" ]; then
        __ORIG_PREFIX__HOME="set:$HOME"
    else
        __ORIG_PREFIX__HOME=unset
    fi
    __COOKIE_HOME_ENV__="$cookie_home"
    HOME="$cookie_home"
    export __ORIG_PREFIX__HOME __COOKIE_HOME_ENV__ HOME
    unset RELEASE_COOKIE
}

# Run a short-lived client node (`stop`/`ping`/`rpc`) without `exec`, so the
# private cookie home is removed even if the node dies before its first
# `-eval` restores it (BT-5185). The foreground node and `remote_console`
# keep `exec` (signals and the tty belong to erl); their directory is removed
# by the node itself, or left behind if it dies first (see deploying.md).
run_client() {
    status=0
    # Background plus `wait`, so a signal to the launcher (Ctrl-C, `timeout`,
    # a supervisor's TERM/HUP) runs the trap at once: it stops the client and
    # cleans up. These verbs are `-noshell` and read no stdin.
    # The cleanup traps are already installed (`export_cookie`); they stop the
    # client once `erl_pid` is set.
    "$ERL" "$@" &
    erl_pid=$!
    wait "$erl_pid" || status=$?
    cleanup_cookie_home
    exit "$status"
}

cleanup_cookie_home() {
    case "$COOKIE_HOME_DIR" in
        */beamtalk-cookie.*) rm -rf "$COOKIE_HOME_DIR" ;;
    esac
}

# This node's own `-sname`: `RELEASE_NODE` if set, else the release name
# (matching `mix release`'s identically-named env var). Deliberately never
# baked into `vm.args` (see `generate_vm_args`'s doc comment) — `erl` uses
# the *first* `-sname` it sees and warns on a duplicate, so a value fixed at
# build time could never be overridden here. This is what lets more than one
# instance of the same release run on one host at once (e.g. local cluster
# testing, ADR 0126 §9): start each with a distinct `RELEASE_NODE`
# (`RELEASE_NODE=symphony1 RELEASE_COOKIE=... bin/symphony foreground`), and
# target the same one with matching `stop`/`ping`/`rpc`/`remote_console`
# calls. `beamtalk_workspace_app:release_workspace_id/0` reads the same
# `RELEASE_NODE` env var for its `workspace_id`, so the REPL port file
# (`~/.beamtalk/workspaces/<workspace_id>/port`) stays distinct too.
node_sname() {
    printf '%s' "${RELEASE_NODE:-$RELEASE_NAME}@localhost"
}

usage() {
    echo "usage: $0 {foreground|stop|ping|remote_console|eval|rpc|version} [args...]" >&2
    echo "  eval/rpc take ONE argument, \"ClassName selector [args...]\", split on whitespace;" >&2
    echo "  an individual argument containing whitespace is not supported." >&2
    exit 2
}

VERB="${1:-foreground}"
if [ $# -gt 0 ]; then
    shift
fi

case "$VERB" in
    foreground)
        check_otp_window
        # `-noshell -noinput`: a service has no interactive tty attached
        # (ADR 0125 §1.7 — "Stdout is the container's stdout", not an Erlang
        # shell prompt). Without these, `erl` attaches an interactive shell
        # that reads stdin; under a process supervisor (systemd, Docker,
        # `nohup`) stdin is typically closed or not a tty, so the shell sees
        # immediate EOF and the whole node terminates seconds after boot —
        # `Console` output (ADR 0099) is unaffected: it still goes to
        # stdout/stderr normally, this only turns off the interactive
        # `1> ` prompt reading from stdin.
        export_cookie
        exec "$ERL" -noshell -noinput -boot "$CONFIG_DIR/start" -boot_var RELEASE_DIR "$ROOT" \
            -sname "$(node_sname)" \
            -config "$CONFIG_DIR/sys" -args_file "$CONFIG_DIR/vm.args"
        ;;
    stop)
        check_otp_window
        SNAME=$(client_sname stop)
        # This instance's own name — see `node_sname`'s comment (respects
        # `RELEASE_NODE`, so `stop` targets whichever instance was started
        # with the same value).
        NODE=$(node_sname)
        export_cookie
        eval "set -- -noshell -hidden -sname \"\$SNAME\" -kernel inet_dist_use_interface '{127,0,0,1}' $(minimal_boot_args) $(lib_pa_args) \
            -eval \"__RESTORE_HOME_EVAL__.\" \
            -eval \"beamtalk_release_launcher:stop_client_main().\" \
            -extra \"\$NODE\""
        run_client "$@"
        ;;
    ping)
        check_otp_window
        SNAME=$(client_sname ping)
        # This instance's own name — see `node_sname`'s comment (respects
        # `RELEASE_NODE`, so `ping` targets whichever instance was started
        # with the same value).
        NODE=$(node_sname)
        export_cookie
        eval "set -- -noshell -hidden -sname \"\$SNAME\" -kernel inet_dist_use_interface '{127,0,0,1}' $(minimal_boot_args) $(lib_pa_args) \
            -eval \"__RESTORE_HOME_EVAL__.\" \
            -eval \"beamtalk_release_launcher:ping_client_main().\" \
            -extra \"\$NODE\""
        run_client "$@"
        ;;
    remote_console)
        check_otp_window
        SNAME=$(client_sname rc)
        # This instance's own name — see `node_sname`'s comment (respects
        # `RELEASE_NODE`, so `remote_console` attaches to whichever instance
        # was started with the same value).
        NODE=$(node_sname)
        # ADR 0091: same-host attach only — plain loopback distribution, no
        # further authentication beyond the cookie handshake (ADR 0058).
        export_cookie
        # Put `HOME` back first (BT-5185), then start the same remote shell
        # `-remsh` does (OTP 26+).
        eval "set -- -noshell -hidden -sname \"\$SNAME\" -kernel inet_dist_use_interface '{127,0,0,1}' $(minimal_boot_args) $(lib_pa_args) \
            -eval \"__RESTORE_HOME_EVAL__, shell:start_interactive({'\$NODE', {shell, start, []}}).\""
        exec "$ERL" "$@"
        ;;
    eval)
        check_otp_window
        [ $# -ge 1 ] || usage
        ARG="$1"
        set -f
        # shellcheck disable=SC2086
        set -- $ARG
        set +f
        [ $# -ge 2 ] || {
            echo "eval requires \"ClassName selector [args...]\"" >&2
            exit 2
        }
        CLASS="$1"
        SELECTOR="$2"
        shift 2
        eval "set -- -noshell $(minimal_boot_args) $(lib_pa_args) \
            -config \"\$CONFIG_DIR/sys\" \
            -beamtalk_workspace console false \
            -eval \"beamtalk_release_launcher:eval_main().\" \
            -extra \"\$CLASS\" \"\$SELECTOR\" \"\$@\""
        exec "$ERL" "$@"
        ;;
    rpc)
        check_otp_window
        [ $# -ge 1 ] || usage
        ARG="$1"
        set -f
        # shellcheck disable=SC2086
        set -- $ARG
        set +f
        [ $# -ge 2 ] || {
            echo "rpc requires \"ClassName selector [args...]\"" >&2
            exit 2
        }
        CLASS="$1"
        SELECTOR="$2"
        shift 2
        SNAME=$(client_sname rpc)
        # This instance's own name — see `node_sname`'s comment (respects
        # `RELEASE_NODE`, so `rpc` targets whichever instance was started
        # with the same value).
        NODE=$(node_sname)
        export_cookie
        eval "set -- -noshell -hidden -sname \"\$SNAME\" -kernel inet_dist_use_interface '{127,0,0,1}' $(minimal_boot_args) $(lib_pa_args) \
            -eval \"__RESTORE_HOME_EVAL__.\" \
            -eval \"beamtalk_release_launcher:rpc_client_main().\" \
            -extra \"\$NODE\" \"\$CLASS\" \"\$SELECTOR\" \"\$@\""
        run_client "$@"
        ;;
    version)
        if [ -f "$PROVENANCE" ]; then
            release=$(grep -o '"release"[[:space:]]*:[[:space:]]*"[^"]*"' "$PROVENANCE" | head -n1 | sed -E 's/.*"([^"]*)"$/\1/')
            release_version=$(grep -o '"release_version"[[:space:]]*:[[:space:]]*"[^"]*"' "$PROVENANCE" | head -n1 | sed -E 's/.*"([^"]*)"$/\1/')
            beamtalk_version=$(grep -o '"beamtalk_version"[[:space:]]*:[[:space:]]*"[^"]*"' "$PROVENANCE" | head -n1 | sed -E 's/.*"([^"]*)"$/\1/')
            otp_release=$(grep -o '"otp_release"[[:space:]]*:[[:space:]]*"[^"]*"' "$PROVENANCE" | head -n1 | sed -E 's/.*"([^"]*)"$/\1/')
            platform=$(grep -o '"platform"[[:space:]]*:[[:space:]]*"[^"]*"' "$PROVENANCE" | head -n1 | sed -E 's/.*"([^"]*)"$/\1/')
            echo "$release $release_version"
            echo "  beamtalk  $beamtalk_version"
            echo "  otp       $otp_release"
            echo "  platform  $platform"
        else
            echo "$RELEASE_NAME $RELEASE_VSN"
        fi
        ;;
    *)
        usage
        ;;
esac
